using OcctSharp.Generator.Discovery;
using OcctSharp.Generator.Emission;
using OcctSharp.Generator.Model;
using OcctSharp.Generator.Transformation;
using System.Security.Cryptography;
namespace OcctSharp.Generator.Tests;
public sealed class NumericResultContractTests {
 static ClosedWorkflowOperationContract Contract=>ClosedWorkflowOperationContract.NumericResults;
 static BindingDeclaration Declaration(CopiedCollectionOperationContract.Operation op)=>new(op.StableId,op.NativeName,BindingDeclarationKind.Function,op.Header!,1,1){NativeSignature=op.Signature,Access=BindingAccess.None,SourcePackage=op.SourcePackage!,ProductModule=OcctProductModule.Foundation};
 [Fact]public void ExactFunctionSourceContractFailsClosed(){foreach(var op in Contract.Operations.Values){var d=Declaration(op);Assert.True(Contract.Contains(d));Assert.False(Contract.Contains(d with{Header="Other.hxx"}));Assert.False(Contract.Contains(d with{SourceToolkit="TKernel"}));Assert.False(Contract.Contains(d with{NativeSignature=d.NativeSignature+" "}));Assert.False(Contract.Contains(d with{IsVariadic=true}));Assert.False(Contract.Contains(d with{SupportState=BindingSupportState.Manual}));}}
 [Fact]public void ResultProfilesRegenerateDeterministicallyAndMissingInputsFail(){var rows=Contract.Operations.Values.Select(Declaration).ToArray();var a=ClosedWorkflowOperationEmitter.Emit("8.0.1",new(rows),Contract);var b=ClosedWorkflowOperationEmitter.Emit("8.0.1",new(rows.Reverse()),Contract);Assert.Equal(5,a.Files.Count);Assert.Equal(a.Files.Select(x=>x.Content),b.Files.Select(x=>x.Content));Assert.Throws<InvalidDataException>(()=>ClosedWorkflowOperationEmitter.Emit("8.0.1",new(rows.Skip(1)),Contract));Assert.Contains(a.Files,x=>x.RelativePath.EndsWith("WorkflowResultSupport.Generated.hxx",StringComparison.Ordinal));}
 [Fact]public void SupplementalIncludesRequireHashesAndRejectMissingOrEscapingSources(){string root=Path.Combine(Path.GetTempPath(),"occtsharp-supplement-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string file=Path.Combine(root,"fixed.pxx");File.WriteAllText(file,"// fixed SDK fragment\n");string hash=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file)));string config=Path.Combine(root,"generation.json");Assert.Equal(root,Assert.Single(SupplementalIncludeResolver.Resolve(config,[new("fixed.pxx",hash)])));Assert.Throws<InvalidDataException>(()=>SupplementalIncludeResolver.Resolve(config,[new("fixed.pxx",new string('0',64))]));Assert.Throws<FileNotFoundException>(()=>SupplementalIncludeResolver.Resolve(config,[new("absent.pxx",hash)]));Assert.Throws<InvalidDataException>(()=>SupplementalIncludeResolver.Resolve(config,[new("../outside.pxx",hash)]));}finally{Directory.Delete(root,true);}}
 [Fact]public void SupplementalIncludeRepairsRealParserInputWithoutChangingInstalledHeader(){string root=Path.Combine(Path.GetTempPath(),"occtsharp-parse-supplement-"+Guid.NewGuid().ToString("N"));string inc=Path.Combine(root,"inc"),extra=Path.Combine(root,"extra");Directory.CreateDirectory(inc);Directory.CreateDirectory(extra);try{File.WriteAllText(Path.Combine(inc,"Standard_Version.hxx"),"#define OCC_VERSION_COMPLETE \"test\"\n");File.WriteAllText(Path.Combine(inc,"Tool.hxx"),"#include <ToolHelper.pxx>\nclass Tool { public: int Value(); };\n");File.WriteAllText(Path.Combine(extra,"ToolHelper.pxx"),"// supplied from fixed source\n");Assert.Throws<InvalidOperationException>(()=>ClangAstDiscovery.Discover(new(root,["Tool.hxx"])));var parsed=ClangAstDiscovery.Discover(new(root,["Tool.hxx"]){AdditionalIncludeDirectories=[extra]});Assert.Contains(parsed.Model.Declarations,x=>x.NativeName=="Tool::Value");Assert.False(File.Exists(Path.Combine(inc,"ToolHelper.pxx")));}finally{Directory.Delete(root,true);}}
}
